const rows = Array.isArray(msg.payload) ? msg.payload : [];
const activeFires = rows.filter(r => r.active === 1);

// Tiempo máximo sin reportar antes de considerar un sensor caído (900s = 15 min para pruebas)
const SENSOR_TIMEOUT_SEC = 900;
const MAX_NEIGHBOR_KM = 100;
const nowMs = Date.now();

function haversineKm(lat1, lon1, lat2, lon2) {
    const R = 6371;
    const dLat = (lat2 - lat1) * Math.PI / 180;
    const dLon = (lon2 - lon1) * Math.PI / 180;
    const a = Math.sin(dLat / 2) ** 2 +
        Math.cos(lat1 * Math.PI / 180) * Math.cos(lat2 * Math.PI / 180) *
        Math.sin(dLon / 2) ** 2;
    return R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
}

// 1. Identificar qué sensores están online
const evaluated = activeFires.map(fire => {
    const updatedMs = fire.updated_at ? Date.parse(fire.updated_at) : 0;
    const ageSec = (nowMs - updatedMs) / 1000;
    const isOnline = ageSec <= SENSOR_TIMEOUT_SEC && fire.wind_speed !== null;
    return { ...fire, isOnline, ageSec: Math.round(ageSec) };
});

const onlineSensorsList = evaluated.filter(f => f.isOnline);

// 2. Calcular dirección de avance del fuego y respaldo por vecino <= 15 km
let criticalCount = 0;
let estimatedCount = 0;

const enrichedFires = evaluated.map(fire => {
    const danger = (fire.danger_level || "UNKNOWN").toUpperCase();
    if (danger === "HIGH" || danger === "EXTREME") criticalCount++;

    let effectiveWindSpeed = fire.wind_speed;
    let effectiveWindDir = fire.wind_direction;
    let windSource = "direct"; // "direct" | "estimated" | "none"
    let neighborInfo = null;

    if (!fire.isOnline) {
        // Buscar el sensor online más cercano dentro de 15 km
        let bestNeighbor = null;
        let minDist = Infinity;

        for (const candidate of onlineSensorsList) {
            if (candidate.fire_id === fire.fire_id) continue;
            const dist = haversineKm(fire.lat, fire.lon, candidate.lat, candidate.lon);
            if (dist <= MAX_NEIGHBOR_KM && dist < minDist) {
                minDist = dist;
                bestNeighbor = candidate;
            }
        }

        if (bestNeighbor) {
            effectiveWindSpeed = bestNeighbor.wind_speed;
            effectiveWindDir = bestNeighbor.wind_direction;
            windSource = "estimated";
            neighborInfo = `${bestNeighbor.sensor_id || bestNeighbor.fire_id} (${minDist.toFixed(1)} km)`;
            estimatedCount++;
        } else {
            effectiveWindSpeed = null;
            effectiveWindDir = null;
            windSource = "none";
        }
    }

    // Open-Meteo da de dónde viene el viento; sumamos 180° para ver hacia dónde avanza el fuego
    const fireAdvanceDir = (effectiveWindDir !== null && effectiveWindDir !== undefined)
        ? (effectiveWindDir + 180) % 360
        : null;

    return {
        ...fire,
        effective_wind_speed: effectiveWindSpeed,
        effective_wind_direction: effectiveWindDir,
        fire_advance_dir: fireAdvanceDir,
        wind_source: windSource,
        neighbor_info: neighborInfo
    };
});

return [
    { payload: enrichedFires.length },       // Salida 1: Total focos activos
    { payload: criticalCount },              // Salida 2: Alertas High/Extreme
    { payload: onlineSensorsList.length },   // Salida 3: Sensores online
    { payload: estimatedCount },             // Salida 4: Focos con viento estimado
    { payload: enrichedFires }               // Salida 5: Datos completos para Mapa/Tabla
];

const fires = Array.isArray(msg.payload) ? msg.payload : [];
const mapItems = [];

const dangerColors = {
    LOW: "#2e7d32",
    MEDIUM: "#f9a825",
    HIGH: "#ef6c00",
    EXTREME: "#c62828",
    UNKNOWN: "#546e7a"
};

for (const fire of fires) {
    const danger = (fire.danger_level || "UNKNOWN").toUpperCase();
    const color = dangerColors[danger] || dangerColors.UNKNOWN;

    const windLabel = fire.wind_source === "direct"
        ? `Direct sensor (${fire.sensor_id})`
        : fire.wind_source === "estimated"
            ? `Estimated via neighbor: ${fire.neighbor_info}`
            : "Sensor offline (no neighbor within 15 km)";

    const popupHtml = `
        <div style="font-family: sans-serif; min-width: 190px;">
            <b>Region:</b> ${fire.region || "Unknown"}<br>
            <b>Danger Level:</b> <span style="color:${color}; font-weight:bold;">${danger}</span><br>
            <b>Temp:</b> ${fire.temperature ?? "N/A"} °C | <b>Humidity:</b> ${fire.humidity ?? "N/A"} %<br>
            <b>Wind Speed:</b> ${fire.effective_wind_speed ?? "N/A"} m/s<br>
            <b>Spread Direction:</b> ${fire.fire_advance_dir !== null ? fire.fire_advance_dir + "°" : "N/A"}<br>
            <b>Wind Source:</b> ${windLabel}<br>
            <b>Origin:</b> ${fire.simulated ? "Simulated" : "NASA FIRMS"}
        </div>
    `;

    // 1. Marcador principal del incendio
    mapItems.push({
        name: fire.fire_id,
        lat: fire.lat,
        lon: fire.lon,
        icon: "fire",
        iconColor: color,
        popuptitle: `Fire ID: ${fire.fire_id}`,
        popup: popupHtml
    });

    // 2. Flecha SVG dinámica rotada según fire_advance_dir
    if (fire.fire_advance_dir !== null && fire.effective_wind_speed !== null) {
        const arrowColor = color;
        const strokeStyle = fire.wind_source === "estimated" ? 'stroke-dasharray="5,3"' : '';
        const angle = fire.fire_advance_dir;

        const arrowSvg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64" width="58" height="58"><polygon points="32,6 52,56 32,44 12,56" fill="${arrowColor}" stroke="#ffffff" stroke-width="3" stroke-linejoin="round" transform="rotate(${angle} 32 32)" ${strokeStyle}/></svg>`;
        const arrowIcon = `data:image/svg+xml;base64,${Buffer.from(arrowSvg).toString("base64")}`;

        mapItems.push({
            name: `${fire.fire_id}_arrow`,
            lat: fire.lat,
            lon: fire.lon,
            icon: arrowIcon,
            iconSize: 58,
            hdg: angle,
            bearing: angle
        });
    }
}

return { payload: mapItems };

const fires = Array.isArray(msg.payload) ? msg.payload : [];

const dangerStyles = {
    LOW: "background:#e8f5e9; color:#2e7d32;",
    MEDIUM: "background:#fff8e1; color:#f57f17;",
    HIGH: "background:#fff3e0; color:#ef6c00;",
    EXTREME: "background:#ffebee; color:#c62828;",
    UNKNOWN: "background:#eceff1; color:#546e7a;"
};

const rows = fires.map(fire => {
    const danger = (fire.danger_level || "UNKNOWN").toUpperCase();
    const badgeStyle = dangerStyles[danger] || dangerStyles.UNKNOWN;

    let sourceText = "Offline (no neighbor ≤ 100 km)";
    let sourceColor = "#c62828";

    if (fire.wind_source === "direct") {
        sourceText = `Direct (${fire.sensor_id || "sensor"})`;
        sourceColor = "#2e7d32";
    } else if (fire.wind_source === "estimated") {
        sourceText = `Estimated via ${fire.neighbor_info}`;
        sourceColor = "#0277bd";
    }

    return {
        fire_id: fire.fire_id,
        region: fire.region || "Unknown",
        danger,
        badgeStyle,
        coords: `${Number(fire.lat).toFixed(4)}, ${Number(fire.lon).toFixed(4)}`,
        weather: `${fire.temperature ?? "N/A"} °C / ${fire.humidity ?? "N/A"} %`,
        wind: fire.effective_wind_speed !== null
            ? `${fire.effective_wind_speed} m/s → ${fire.fire_advance_dir}°`
            : "N/A",
        sourceText,
        sourceColor,
        origin: fire.simulated ? "Simulated" : "NASA FIRMS"
    };
});

return { payload: rows };

const line = String(msg.payload || "").trim();
if (!line) return null; // Ignora líneas vacías

// Recupera la lista actual (o crea una vacía)
let alerts = context.get("alerts") || [];

// Añade la hora y el mensaje nuevo al principio de la lista
const time = new Date().toLocaleTimeString("es-ES");
alerts.unshift(`[${time}] ${line}`);

// Mantiene solo las últimas 10 alertas para no saturar la pantalla
if (alerts.length > 10) {
    alerts = alerts.slice(0, 10);
}

context.set("alerts", alerts);

// Une toda la lista con saltos de línea para que el nodo 'text' la pinte entera
msg.payload = alerts.join("\n");
return msg;

